const s=require('../../../../miniprogram/utils/service'),d=require('../../../../miniprogram/utils/domain');
Page({data:{busy:false,error:'',loaded:false,recipes:[],filtered:[],category:'全部',tab:'菜单',query:'',week:d.weekKey(),counts:{},options:{},coverage:{meatMeals:0,vegMeals:0,meatKinds:0,vegKinds:0},editing:null,favorites:[],tabs:['菜单','常点','收藏'],categories:['全部','荤菜','素菜'],total:0},onShow(){return this.load();},async load(){await s.run(this,async()=>{const c=await s.call();if(c.unbound)throw Error('先到“我们”创建或加入家庭');this.state=c.state;const draft=s.draft(this.data.week),p=c.state.plans[this.data.week];const counts=draft?draft.counts:Object.fromEntries((p?p.lines:[]).map(l=>[l.id,l.count]));const options=draft&&draft.options||Object.fromEntries((p?p.lines:[]).map(l=>[l.id,{spice:l.spice||'不辣',servings:l.servings||1}]));const me=c.state.members.find(x=>x.id===c.uid);const favorites=me.favorites||[];const frequency={};for(const plan of Object.values(c.state.plans))for(const l of plan.lines)frequency[l.id]=(frequency[l.id]||0)+l.count;this.setData({loaded:true,recipes:c.state.recipes.map(x=>({...x,image:s.display(x),frequency:frequency[x.id]||0,favorite:favorites.includes(x.id)})),counts,options,favorites});this.filter();});},onPullDownRefresh(){this.load().finally(()=>wx.stopPullDownRefresh());},filter(){const {recipes,query,category,tab,counts,options}=this.data;let filtered=recipes.filter(x=>(category==='全部'||x.category===category)&&x.name.includes(query)&&(tab!=='收藏'||x.favorite)&&(tab!=='常点'||x.frequency>0));if(tab==='常点')filtered.sort((a,b)=>b.frequency-a.frequency);filtered=filtered.map(x=>({...x,count:counts[x.id]||0,spice:(options[x.id]||{}).spice||'不辣',servings:(options[x.id]||{}).servings||1}));const lines=Object.entries(counts).map(([id,count])=>({id,count}));this.setData({filtered,coverage:d.coverage(recipes,lines),total:lines.filter(x=>x.count>0).length});},search(e){this.setData({query:e.detail.value});this.filter();},category(e){this.setData({category:e.currentTarget.dataset.value});this.filter();},tab(e){this.setData({tab:e.currentTarget.dataset.value});this.filter();},open(e){const id=e.currentTarget.dataset.id,r=this.data.recipes.find(x=>x.id===id),o=this.data.options[id]||{};this.setData({editing:{id,name:r.name,image:r.image,spice:o.spice||'不辣',servings:o.servings||1,count:this.data.counts[id]||3}});},cancel(){this.setData({editing:null});},spice(e){this.setData({editing:{...this.data.editing,spice:e.currentTarget.dataset.value}});},adjust(e){const {key,delta}=e.currentTarget.dataset;const x=this.data.editing;this.setData({editing:{...x,[key]:Math.max(1,Math.min(key==='count'?9:6,Number(x[key])+Number(delta)))}});},save(){const x=this.data.editing;this.setData({counts:{...this.data.counts,[x.id]:x.count},options:{...this.data.options,[x.id]:{spice:x.spice,servings:x.servings}},editing:null});this.persist();this.filter();},remove(e){const id=e.currentTarget.dataset.id;this.setData({counts:{...this.data.counts,[id]:0}});this.persist();this.filter();},persist(){const old=s.draft(this.data.week)||{};s.saveDraft(this.data.week,{...old,counts:this.data.counts,options:this.data.options});},async favorite(e){await s.run(this,()=>s.call('favorite',{id:e.currentTarget.dataset.id}));await this.load();},review(){wx.switchTab({url:'/pages/week/index'});},setup(){wx.switchTab({url:'/pages/home/index'});}});
